document.querySelectorAll('[data-lab="L06-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const ion=root.querySelector('[data-ion]'),dist=root.querySelector('[data-distance]'),angle=root.querySelector('[data-angle]'),en=root.dataset.lang==='en';const C=332.06371,l=.9572,d=.1546,h=104.52*Math.PI/360;function sites(R,b){return{O:[R,0],M:[R+d*Math.cos(b),d*Math.sin(b)],H1:[R+l*Math.cos(b+h),l*Math.sin(b+h)],H2:[R+l*Math.cos(b-h),l*Math.sin(b-h)]};}function energy(R,a,q){const p=sites(R,a*Math.PI/180);return C*q*(-1.1128/Math.hypot(...p.M)+.5564/Math.hypot(...p.H1)+.5564/Math.hypot(...p.H2));}function draw(){const R=+dist.value,b=+angle.value,q=+ion.value,p=sites(R,b*Math.PI/180);root.querySelector('[data-r]').textContent=R.toFixed(2);root.querySelector('[data-beta]').textContent=b.toFixed(0);root.querySelector('[data-ion-label]').textContent=q>0?'Na⁺':'Cl⁻';const point=v=>[100+70*v[0],135-70*v[1]];for(const key of ['O','M','H1','H2']){const xy=point(p[key]),el=root.querySelector('[data-'+key.toLowerCase()+']');el.setAttribute('cx',xy[0]);el.setAttribute('cy',xy[1]);}for(const [i,key] of [[1,'H1'],[2,'H2']]){const a=point(p.O),b=point(p[key]),el=root.querySelector('[data-bond'+i+']');['x1','y1','x2','y2'].forEach((k,j)=>el.setAttribute(k,[...a,...b][j]));}const vals=Array.from({length:181},(_,i)=>energy(R,i,q)),vmin=Math.min(...vals),vmax=Math.max(...vals),span=vmax-vmin,lo=vmin-.08*span,hi=vmax+.08*span,map=(a,u)=>[80+740*a/180,510-195*(u-lo)/(hi-lo)];root.querySelector('[data-curve]').setAttribute('points',vals.map((u,i)=>map(i,u).join(',')).join(' '));const xy=map(b,energy(R,b,q));root.querySelector('[data-marker]').setAttribute('cx',xy[0]);root.querySelector('[data-marker]').setAttribute('cy',xy[1]);root.querySelector('[data-yhi]').textContent=hi.toFixed(1);root.querySelector('[data-ylo]').textContent=lo.toFixed(1);root.querySelector('[data-answer]').textContent='U = '+energy(R,b,q).toFixed(5)+' kcal mol⁻¹; cos β = '+Math.cos(b*Math.PI/180).toFixed(3)+'. '+(en?'The curve sums the ion interactions with M and both H charges.':'曲线相加离子与M及两个H电荷的直接作用。');}ion.addEventListener('change',draw);dist.addEventListener('input',draw);angle.addEventListener('input',draw);root.querySelector('[data-reset]').addEventListener('click',()=>{ion.value='1';dist.value='3.5';angle.value='0';draw();});draw();});